mapper.select:
Select v.* From (Select pp.project_id, pp.project_number, nvl(pp.sign_status,'NEW') sign_status, (Select v.meaning From sys_code_value_b_v v Where v. CODE = 'SIGN_STATUS' And v.code_value = nvl(pp.sign_status,'NEW')) sign_status_n, pp.project_status, (select description from hls_document_status where document_category = 'PRJ_PROJECT' and status_code = pp.project_status) project_status_n, pp.sign_type, (Select v.meaning From sys_code_value_b_v v Where v. CODE = 'SIGN_METHOD' And v.code_value = pp.sign_type) sign_type_n, pp.tenant_id, (Select hm.bp_name From hls_bp_master hm Where hm.bp_id = pp.tenant_id) tenant_id_n, pp.factory_id, (Select hm.bp_name From hls_bp_master hm Where hm.bp_id = pp.factory_id) factory_id_n, pp.bp_id_vender, (Select hm.bp_name From hls_bp_master hm Where hm.bp_id = pp.bp_id_vender) bp_id_vender_n, pp.lease_channel, (Select hc.description From hls_lease_channel hc Where hc.lease_channel = pp.lease_channel) lease_channel_n, pp.document_type, (SELECT v.description value_name FROM hls_document_type v WHERE V.enabled_flag = 'Y' AND v.document_category = 'PRJ_PROJECT_IMPORT' and v.document_type in ('PRJL', 'PRJLB') AND v.document_type = pp.document_type) document_type_n, pp.employee_id, (Select fe.name From fnd_employee fe Where fe.employee_id = pp.employee_id) employee_id_n, pp.lease_organization, (Select fu.unit_name From fnd_org_unit fu Where fu.unit_code = pp.lease_organization And fu.enabled_flag = 'Y') lease_organization_n, nvl(pp.org_sign_state,'NEW') org_sign_state, (Select v.meaning From sys_code_value_b_v v Where v.CODE = 'ORG_SIGN_STATE' And v.code_value = nvl(pp.org_sign_state,'NEW')) org_sign_state_n, pp.manufacturer_id, pp.division,pp.signed_flag, (select hbm.phone from hls_bp_master hbm where hbm.bp_id = pp.factory_id) phone, (select hbm.id_card_no from hls_bp_master hbm where hbm.bp_id = pp.factory_id) id_card_no, (SELECT PROJECT_ATTACHMENT_ID FROM PRJ_PROJECT_ATTACHMENT pa WHERE pa.PROJECT_ID = pp.PROJECT_ID AND pa.PROJECT_ATTACHMENT_CATEGORY = 'ONLINE_SIGN_CONTRACT' AND ROWNUM <= 1) PROJECT_ATTACHMENT_ID From prj_project pp Where pp.signed_flag = 'Y') v
and v.project_id = #{project_id}
and v.project_number like concat(concat('%',#{project_number}),'%')
and v.bp_id_tenant_n like concat(concat('%',#{bp_id_tenant_n}),'%')
and v.bp_id_vender = #{bp_id_vender}
and v.org_sign_state = #{org_sign_state}
and (v.factory_id = #{bp_id} or #{user_name} = 'admin')
and (v.bp_id_vender = #{bp_id} or #{user_name}='admin')
order by v.project_number desc

select * from PRJ_SIGN_RECORD where sign_id =
(
    SELECT max(sign_id) FROM "PRJ_SIGN_RECORD"
    where source_doc_category = #{docCategory} and source_doc_id =#{docId}
)
